"Tady jde Pawkur jen prohlížet. Ikona na ploše a upozornění jdou z Chromu.":"Hier kannst du Pawkur nur ansehen. Das Icon auf dem Startbildschirm und Benachrichtigungen gibt es nur über Chrome.",
"Tady jde Pawkur jen prohlížet. Ikona na ploše a upozornění jdou ze Safari: klepni na ⋯ vpravo nahoře a zvol Otevřít v Safari.":"Hier kannst du Pawkur nur ansehen. Das Icon auf dem Home-Bildschirm und Benachrichtigungen gibt es nur über Safari: Tippe oben rechts auf ⋯ und wähle „In Safari öffnen“.",
