"Bližším koncem":"Näheres Ende",
"Pes vběhne do překážky koncem, který je blíž předchozí překážce.":"Der Hund läuft am Ende hinein, das näher am vorherigen Hindernis liegt.",
"Vzdálenějším koncem":"Entferntes Ende",
"Pes překážku oběhne a vběhne do ní z druhé strany, třeba do odvráceného konce tunelu.":"Der Hund läuft um das Hindernis herum und von der anderen Seite hinein, z. B. ins abgewandte Tunnelende.",
"Aplikace sama volí konec, který je blíž předchozí překážce. Když trenér posílá psa do vzdálenějšího konce, přepni to tady.":"Die App wählt selbst das Ende, das näher am vorherigen Hindernis liegt. Schickt der Trainer den Hund ins entfernte Ende, stell es hier um.",
"Bez otočky":"Ohne Wickler",
"Pes skok skočí a běží rovnou k další překážce.":"Der Hund nimmt den Sprung und läuft direkt zum nächsten Hindernis.",
"Skok z druhé strany":"Sprung von der anderen Seite",
"Aplikace volí směr skoku podle toho, odkud pes přibíhá. Když ho trenér posílá na skok z opačné strany, přepni to tady.":"Die App wählt die Sprungrichtung danach, woher der Hund kommt. Schickt der Trainer ihn von der anderen Seite über den Sprung, stell es hier um.",
"Otočka doleva":"Wickler links",
"Po skoku se pes otočí o 180° kolem levého křídla.":"Nach dem Sprung wendet der Hund um 180° um den linken Flügel.",
"Otočka doprava":"Wickler rechts",
"Po skoku se pes otočí o 180° kolem pravého křídla.":"Nach dem Sprung wendet der Hund um 180° um den rechten Flügel.",
"Zadní strana, otočka doleva":"Backside, Wickler links",
"Pes skok mine, oběhne křídlo doleva a skočí ho z druhé strany.":"Der Hund läuft am Sprung vorbei, links um den Flügel und springt ihn von der anderen Seite.",
"Zadní strana, otočka doprava":"Backside, Wickler rechts",
"Pes skok mine, oběhne křídlo doprava a skočí ho z druhé strany.":"Der Hund läuft am Sprung vorbei, rechts um den Flügel und springt ihn von der anderen Seite.",
"Pes běží u psovoda vlevo, takže otočka doprava je vnitřkem (k psovodovi) a otočka doleva venkem (od psovoda).":"Der Hund läuft links von dir, also ist der Wickler rechts innen (zu dir) und der Wickler links außen (von dir weg).",
"Pes běží u psovoda vlevo, takže otočka doprava je vnitřkem (k psovodovi) a otočka doprava venkem (od psovoda).":"Der Hund läuft links von dir, also ist der Wickler rechts innen (zu dir) und der Wickler rechts außen (von dir weg).",
"Pes běží u psovoda vlevo, takže otočka doleva je vnitřkem (k psovodovi) a otočka doleva venkem (od psovoda).":"Der Hund läuft links von dir, also ist der Wickler links innen (zu dir) und der Wickler links außen (von dir weg).",
"Pes běží u psovoda vlevo, takže otočka doleva je vnitřkem (k psovodovi) a otočka doprava venkem (od psovoda).":"Der Hund läuft links von dir, also ist der Wickler links innen (zu dir) und der Wickler rechts außen (von dir weg).",
"Pes běží u psovoda vpravo, takže otočka doprava je vnitřkem (k psovodovi) a otočka doleva venkem (od psovoda).":"Der Hund läuft rechts von dir, also ist der Wickler rechts innen (zu dir) und der Wickler links außen (von dir weg).",
"Pes běží u psovoda vpravo, takže otočka doprava je vnitřkem (k psovodovi) a otočka doprava venkem (od psovoda).":"Der Hund läuft rechts von dir, also ist der Wickler rechts innen (zu dir) und der Wickler rechts außen (von dir weg).",
"Pes běží u psovoda vpravo, takže otočka doleva je vnitřkem (k psovodovi) a otočka doleva venkem (od psovoda).":"Der Hund läuft rechts von dir, also ist der Wickler links innen (zu dir) und der Wickler links außen (von dir weg).",
"Pes běží u psovoda vpravo, takže otočka doleva je vnitřkem (k psovodovi) a otočka doprava venkem (od psovoda).":"Der Hund läuft rechts von dir, also ist der Wickler links innen (zu dir) und der Wickler rechts außen (von dir weg).",
"Doleva a doprava je z pohledu psa. Když v Dráze psovoda nastavíš, na které straně psovoda pes běží, aplikace ukáže, jestli je otočka vnitřkem (k psovodovi), nebo venkem (od psovoda).":"Links und rechts gelten aus Sicht des Hundes. Wenn du im Laufweg festlegst, auf welcher Seite von dir der Hund läuft, zeigt die App, ob ein Wickler innen (zu dir) oder außen (von dir weg) ist.",
"+ otočka":"+ Wickler",
"P":"R",
"Zatím žádná trasa. Přepni na Trasa a klepej na překážky v pořadí.":"Noch keine Route. Wechsle zu „Route“ und tippe die Hindernisse der Reihe nach an.",
"Zachovat poměr":"Seitenverhältnis beibehalten",
"Vyber překážku a klepnutím ji polož na plochu. Tažením ji přesuneš, posuvníkem otočíš.":"Wähle ein Hindernis und tippe auf die Fläche, um es zu platzieren. Ziehen verschiebt es, mit dem Schieberegler drehst du es.",
"Klepej na překážky v pořadí, v jakém je pes poběží. Stejnou překážku můžeš použít víckrát. Otočku kolem křídla nebo zadní stranu nastavíš u skoku v seznamu pod plochou.":"Tippe die Hindernisse in der Reihenfolge an, in der der Hund sie läuft. Dasselbe Hindernis kannst du mehrmals verwenden. Wickler oder Backside stellst du beim Sprung in der Liste unter der Fläche ein.",
"Smazat trasu?":"Route löschen?",
"Překážky zůstanou na ploše, smaže se jen pořadí.":"Die Hindernisse bleiben auf der Fläche, nur die Reihenfolge wird gelöscht.",
"Rozestupy (FCI: po dráze 5–9 m, vzdušnou čarou nejvýš 7 m)":"Abstände (FCI: 5–9 m entlang der Lauflinie, Luftlinie max. 7 m)",
"Slalom chybí (FCI: v každém parkuru, jen jednou)":"Slalom fehlt (FCI: in jedem Parcours, nur einmal)",
"Změny strany psovoda: v Dráze psovoda nastav stranu psa u všech překážek (FCI chce aspoň 2)":"Seitenwechsel: Leg im Laufweg bei allen Hindernissen die Hundeseite fest (FCI verlangt mind. 2)",
"Dráha psa nevede přes jinou překážku":"Lauflinie führt über kein anderes Hindernis",
"Podrobnosti":"Details",
"Pravidla FCI v pořádku":"FCI-Regeln eingehalten",
"Kontrola podle pravidel FCI":"Prüfung nach FCI-Regeln",
"Rozestupy se měří po dráze psa, jak ji ukazuje plán, i se smyčkami otoček. Pravidla platí pro závody, na trénink si můžeš postavit cokoli.":"Die Abstände werden entlang der Lauflinie gemessen, wie sie der Plan zeigt, inklusive Wickler-Schleifen. Die Regeln gelten für Turniere, im Training kannst du bauen, was du willst.",
"Fotku jako podklad vložíš ve webové verzi aplikace.":"Ein Foto als Hintergrund fügst du in der Web-Version der App ein.",
"Podklad odebrán":"Hintergrund entfernt",
"Podklad vložen":"Hintergrund eingefügt",
"Tenhle soubor se nepodařilo načíst jako obrázek.":"Diese Datei ließ sich nicht als Bild laden.",
"Trénink paměti potřebuje trasu aspoň se 3 překážkami.":"Das Gedächtnistraining braucht eine Route mit mindestens 3 Hindernissen.",
"Prohlídka: zapamatuj si pořadí překážek.":"Begehung: Merk dir die Reihenfolge der Hindernisse.",
