"V téhle záložce nic nového není. Nové parkury mají štítek Nový a tečku u názvu záložky.":"In diesem Tab gibt es nichts Neues. Neue Parcours haben das Label „Neu“ und einen Punkt am Tab-Namen.",
"Zatím tu nejsou žádné parkury trenérů. Pošli do chatu s Claudem screenshoty plánků a přepíše je sem i se jménem autora. Nebo v Plánu zvol Plánek z obrázku: aplikace překážky rozpozná, pořadí naklepeš a při ukládání vyplníš, kdo parkur stavěl.":"Noch keine Trainer-Parcours. Schick Screenshots der Skizzen in den Chat mit Claude, dann überträgt er sie hierher, samt Name des Autors. Oder wähle im Plan „Skizze aus Bild“: Die App erkennt die Hindernisse, du tippst die Reihenfolge an und gibst beim Speichern an, wer den Parcours gestellt hat.",
"Zatím tu nemáš žádný vlastní parkur. Postav ho v Plánu nebo si otevři některý z A1–A3, uprav ho a ulož.":"Du hast noch keinen eigenen Parcours. Bau einen im Plan oder öffne einen aus A1–A3, bearbeite ihn und speichere ihn.",
"V tomhle filtru nic není. Zkus jiný filtr nebo třídu.":"In diesem Filter ist nichts. Versuch einen anderen Filter oder eine andere Klasse.",
"Přepsané plánky trenérů a rozhodčích pro vlastní trénink. Rozmístění překážek je přibližné, zdroj je uvedený u parkuru.":"Übertragene Skizzen von Trainern und Richtern für dein eigenes Training. Die Position der Hindernisse ist ungefähr, die Quelle steht beim Parcours.",
"Parkury A1–A3 složil generátor v aplikaci podle Řádu agility FCI a podle toho, jak stavějí rozhodčí: dráha vede v obloucích a hadech, skoky stojí šikmo, tunely jsou i do oblouku a do U a dráha se kříží (A1 nejvýš jednou, A2 jednou až dvakrát, A3 dvakrát až třikrát). 15–22 překážek, start i cíl skokem, v A1 právě 3 zónové překážky, v A2 a A3 nejvýš 4. Otočky kolem křídla (v A3 aspoň dvě), v A3 vždy i zadní strana skoku.":"Die Parcours A1–A3 hat der Generator der App nach dem FCI-Agility-Reglement erstellt, und zwar so, wie Richter stellen: Die Lauflinie führt in Bögen und Serpentinen, Sprünge stehen schräg, Tunnel sind auch gebogen oder in U-Form, und die Lauflinie kreuzt sich (A1 höchstens einmal, A2 ein- bis zweimal, A3 zwei- bis dreimal). 15–22 Hindernisse, Start und Ziel über einen Sprung, in A1 genau 3 Zonengeräte, in A2 und A3 höchstens 4. Wickler um den Flügel (in A3 mindestens zwei), in A3 immer auch eine Backside.",
"Nahradit rozpracovaný plán?":"Angefangenen Plan ersetzen?",
"Neuložené změny se ztratí. Chceš je zachovat, zruš to a nejdřív plán ulož.":"Nicht gespeicherte Änderungen gehen verloren. Willst du sie behalten, brich ab und speichere zuerst den Plan.",
"Parkur zmizí ze záložky Moje. Zapsané běhy se smažou s ním.":"Der Parcours verschwindet aus „Meine“. Die eingetragenen Läufe werden mitgelöscht.",
"V záložce Moje už máš zaběhnuté všechno.":"In „Meine“ bist du schon alles gelaufen.",
