"Plánky od rozhodčích a trenérů. Parkur podle plánku přeneseš v Plánu přes Plánek z obrázku (překážky se rozpoznají samy) a při ukládání vyplníš, kdo ho stavěl.":"Skizzen von Richtern und Trainern. Einen Parcours aus einer Skizze überträgst du im Plan über „Skizze aus Bild“ (die Hindernisse werden automatisch erkannt) und gibst beim Speichern an, wer ihn gestellt hat.",
"HandlerMap 1.9":"HandlerMap 1.9",
"Plánovač agility parkurů: 90 parkurů podle pravidel FCI a stylu rozhodčích (oblouky, křížení, tunely do oblouku), parkury trenérů, kontrola pravidel, výpočet SČP a MČP, stopky s hodnocením a mezičasy, otočky kolem křídla a zadní strany skoků, 3D průlet, trénink paměti, videa s technikou, deník a statistiky.":"Planer für Agility-Parcours: 90 Parcours nach FCI-Regeln und im Stil der Richter (Bögen, Kreuzungen, gebogene Tunnel), Trainer-Parcours, Regelprüfung, Berechnung von SZ und MZ, Stoppuhr mit Bewertung und Zwischenzeiten, Wickler um den Flügel und Backsides, 3D-Durchflug, Gedächtnistraining, Technik-Videos, Tagebuch und Statistiken.",
"Novinky v 1.9: aplikace k instalaci do telefonu (Chrome → Instalovat aplikaci). V ní funguje výběr fotky a videa, ukládání obrázku, PDF a zálohy, plánek jde poslat přes Sdílet z galerie rovnou do čtečky, katalog parkurů i záloha v cloudu. Aktualizuje se sama.":"Neu in 1.9: App zum Installieren aufs Handy (Chrome → App installieren). Darin funktionieren Foto- und Videoauswahl, das Speichern von Bild, PDF und Backup, eine Skizze lässt sich über „Teilen“ aus der Galerie direkt an die Erkennung schicken, dazu Parcours-Katalog und Cloud-Backup. Sie aktualisiert sich selbst.",
"Novinky v 1.8: Plánek z obrázku přečte i trasu. Z čísel v kroužcích pozná pořadí, z nakreslené čáry směry skoků, vstupy do tunelů a zón, otočky kolem křídla a zadní strany. Chybějící kruh, skok daleký, dvojité břevno, zeď nebo kladinu dohledá u čísla. Nejistá místa označí otazníkem. V aplikaci pro Android jde plánek vložit i ze schránky.":"Neu in 1.8: „Skizze aus Bild“ liest auch die Route. Aus den Nummern in den Kreisen erkennt sie die Reihenfolge, aus der gezeichneten Linie die Sprungrichtungen, Eingänge in Tunnel und Zonen, Wickler um den Flügel und Backsides. Fehlende Reifen, Weitsprung, Doppelsprung, Mauer oder Steg findet sie über die Nummer. Unsichere Stellen markiert sie mit einem Fragezeichen. In der Android-App kannst du die Skizze auch aus der Zwischenablage einfügen.",
"Novinky v 1.7: tlačítko Zkontrolovat nové parkury v záložce Parkury, nové parkury mají štítek Nový a tečku u záložky, přibyl parkur trenéra Euskadi Sextuple 2018 A1.":"Neu in 1.7: Button „Nach neuen Parcours suchen“ im Tab „Parcours“, neue Parcours haben das Label „Neu“ und einen Punkt am Tab, dazu der Trainer-Parcours Euskadi Sextuple 2018 A1.",
"Novinky v 1.6: nový generátor parkurů, náročnost a řazení parkurů, rozbor parkuru s vedením psovoda, odhadem času a simulací Stihnu to?, dráha podle velikosti psa, klasická cvičení a klubový parkur v generátoru, mezičasy naživo i z videa, chytrý trénink, předčítání trasy, plánek z obrázku, stavba v terénu s kompasem a sekce Začínáme pro štěňata.":"Neu in 1.6: neuer Parcours-Generator, Schwierigkeit und Sortierung der Parcours, Parcours-Analyse mit Handling, Zeitschätzung und der Simulation „Schaff ich das?“, Lauflinie nach Größe des Hundes, klassische Übungen und Vereinsparcours im Generator, Zwischenzeiten live und aus Video, smartes Training, Route vorlesen, Skizze aus Bild, Aufbau vor Ort mit Kompass und der Bereich „Einstieg“ für Welpen.",
"Data se ukládají v tomhle zařízení. Sdílení kódem a cloudová záloha běží přes server Supabase a fungují v aplikaci pro Android. Uložení PDF a obrázku do telefonu a podklad z fotky fungují ve webové verzi.":"Die Daten werden auf diesem Gerät gespeichert. Teilen per Code und Cloud-Backup laufen über den Supabase-Server und funktionieren in der Android-App. PDF und Bild aufs Handy speichern und Foto als Hintergrund funktionieren in der Web-Version.",
"Pravidla:":"Regeln:",
"Řád agility FCI a ČR (od 2023)":"Agility-Reglement der FCI und Tschechiens (ab 2023)",
"Katalog parkurů: vestavěný. V aplikaci pro Android se nové parkury stáhnou samy při spuštění nebo tlačítkem Zkontrolovat nové parkury v záložce Parkury, bez aktualizace aplikace.":"Parcours-Katalog: integriert. In der Android-App werden neue Parcours beim Start oder mit dem Button „Nach neuen Parcours suchen“ im Tab „Parcours“ automatisch geladen, ohne App-Update.",
