"Plynulost dráhy":"Fluss der Lauflinie",
"Nástraha: překážka, na kterou pes míří v přímém směru, zatímco trasa pokračuje obratem jinam.":"Verleitung: ein Hindernis, auf das der Hund geradeaus zuläuft, während die Route mit einer Wendung woandershin weitergeht.",
"Dráha v plánu":"Lauflinie im Plan",
"Ideální":"Ideal",
"Malý pes zatáčí těsněji a kolem křídla projde blíž, velký v širších obloucích. Délka trati, SČP a kontrola FCI se počítají vždy z ideální čáry.":"Ein kleiner Hund wendet enger und läuft näher am Flügel vorbei, ein großer in weiteren Bögen. Parcourslänge, SZ und FCI-Prüfung werden immer anhand der Ideallinie berechnet.",
"Parkur bez výrazných záludností.":"Parcours ohne besondere Tücken.",
"Vedení psovoda":"Handling",
"Celý parkur se dá vést z jedné strany.":"Den ganzen Parcours kannst du von einer Seite führen.",
"Nastavit stranu psa v Dráze psovoda":"Hundeseite im Laufweg festlegen",
"Odhad času":"Zeitschätzung",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Až zapíšeš běhy psa, odhad se podle nich upraví.":"Hundemodell nach Größe: Tempo in Kurven je nach Radius, Beschleunigung, Abbremsen auf Zonen, im Slalom und auf der Wippe. Sobald du Läufe des Hundes einträgst, passt sich die Schätzung daran an.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Přidej psa ve Více › Psi a odhad bude pro něj.":"Hundemodell nach Größe: Tempo in Kurven je nach Radius, Beschleunigung, Abbremsen auf Zonen, im Slalom und auf der Wippe. Füg unter Mehr › Hunde einen Hund hinzu, dann gilt die Schätzung für ihn.",
"SČP – s":"SZ – s",
"Stihnu to?":"Schaff ich das?",
"Přehrát psa a psovoda":"Hund und Hundeführer abspielen",
"Při téhle rychlosti stihneš být všude včas.":"Bei diesem Tempo bist du überall rechtzeitig.",
"Strana psa nastavena podle návrhu":"Hundeseite nach Vorschlag festgelegt",
"Hnědý je pes, modrý psovod. Klepnutím na plochu zastavíš.":"Braun ist der Hund, blau bist du. Tipp auf die Fläche, um anzuhalten.",
