"Vyber video běhu z telefonu. Zůstane jen v telefonu, nikam se nenahrává.":"Wähle ein Video des Laufs auf deinem Handy. Es bleibt auf dem Handy und wird nirgends hochgeladen.",
"Nejdřív vyber video.":"Wähle zuerst ein Video.",
"Tahle značka je dřív než předchozí. Posuň video dopředu.":"Diese Marke liegt vor der vorherigen. Spul das Video weiter.",
