". Úseky se porovnávají s modelem psa přepočteným na stejný celkový čas, takže je vidět, kde se ztrácí čas oproti zbytku běhu.":". Die Abschnitte werden mit dem Hundemodell verglichen, umgerechnet auf dieselbe Gesamtzeit. So siehst du, wo im Vergleich zum Rest des Laufs Zeit verloren geht.",
