"Do žebříčku se pošle přezdívka, jméno a velikost psa a výsledek. Počítá se tvůj nejlepší běh v týdnu.":"An die Rangliste gehen dein Spitzname, Name und Größe des Hundes und das Ergebnis. Es zählt dein bester Lauf der Woche.",
