"Větší tlačítka a plynulejší přechody":"Größere Buttons und flüssigere Übergänge",
"Novinky v 1.13: 3D animace techniky ve Videích – pes a psovod na skutečných překážkách (skok, tunel, slalom, áčko, kladina, houpačka, kruh, skok daleký) i při vedení psa (čelo, záda, blind, otočky, zadní strana, start). Animace se stáhne až při otevření tématu, na slabším telefonu se sama zjednoduší a bez podpory 3D zůstane dosavadní 2D animace.":"Neu in 1.13: 3D-Technikanimationen unter „Videos“ – Hund und Hundeführer an echten Hindernissen (Sprung, Tunnel, Slalom, A-Wand, Steg, Wippe, Reifen, Weitsprung) und beim Handling (Front Cross, Rear Cross, Blind Cross, Wickler, Backside, Start). Die Animation wird erst beim Öffnen eines Themas geladen, vereinfacht sich auf schwächeren Handys selbst, und ohne 3D-Unterstützung bleibt die bisherige 2D-Animation.",
"Novinky v 1.12: nová úvodní obrazovka Domů – série tréninkových dní, zaběhnuté parkury, průměrná rychlost a podíl čistých běhů, tlačítko Pokračovat na rozdělaný parkur, Parkury pro tebe podle třídy psa, Výzva dne a přehled tréninků v tomto týdnu. Parkur týdne: každý týden jeden parkur pro třídu, výsledek pošleš do žebříčku a porovnáš se s ostatními podle velikosti psa.":"Neu in 1.12: neue Startseite – Serie von Trainingstagen, gelaufene Parcours, Durchschnittstempo und Anteil fehlerfreier Läufe, Button „Weiter“ zum angefangenen Parcours, „Parcours für dich“ passend zur Klasse des Hundes, Tageschallenge und Übersicht der Trainings dieser Woche. Parcours der Woche: jede Woche ein Parcours pro Klasse, dein Ergebnis schickst du an die Rangliste und vergleichst dich mit anderen nach Größe des Hundes.",
"Novinky v 1.11: aplikace se aktualizuje hned a nabídne Obnovit, když je připravená nová verze. STOP na stopkách je dál od Mezičasů, větší tlačítka pro palec (počítadla chyb, překážky na ploše, strana psa L/P), parkury po dvou vedle sebe i na malém telefonu, plocha při klepání trasy neposkakuje, klávesnice nepřekrývá tlačítka. Kontrola FCI počítá mezi skoky i kruh a skok daleký, hlídá nejvýš 5 průběhů tunelem a SČP i MČP vychází z ukázané délky trati.":"Neu in 1.11: Die App aktualisiert sich sofort und bietet „Laden“ an, wenn eine neue Version bereit ist. STOP auf der Stoppuhr liegt weiter weg von den Zwischenzeiten, größere Buttons für den Daumen (Fehlerzähler, Hindernisse auf der Fläche, Hundeseite L/R), Parcours zu zweit nebeneinander auch auf kleinen Handys, die Fläche springt beim Antippen der Route nicht mehr, die Tastatur verdeckt keine Buttons. Die FCI-Prüfung zählt auch Reifen und Weitsprung zu den Sprüngen, achtet auf höchstens 5 Tunneldurchgänge, und SZ wie MZ ergeben sich aus der angezeigten Parcourslänge.",
"Novinky v 1.10: tlačítko Zpět (↶ vedle Stavba / Trasa, na počítači Ctrl+Z) vrátí posunutí, otočení i smazání překážky a změny trasy. Když běží stopky, obrazovka nezhasne. Tažení překážky je plynulejší. Čas ručně jde zadat i jako 1:05,30. Plánek z obrázku při čtení nezamrzne telefon a kompas ve Stavbě v terénu funguje i na iPhonu. PDF se stavebním plánem se vejde i u čtvercové plochy. Parkur z kódu se před uložením zkontroluje, poškozená data už aplikaci neshodí. Obnova zálohy nahradí všechna data, a když se nepovede, nic se nezmění. Při plné paměti aplikace upozorní, že se změna neuložila. Při slabém signálu na cvičišti se aplikace otevře do 3 sekund z uložené verze a písmo funguje i offline.":"Neu in 1.10: Der Button „Zurück“ (↶ neben Aufbau / Route, am Computer Strg+Z) macht Verschieben, Drehen und Löschen von Hindernissen sowie Änderungen der Route rückgängig. Solange die Stoppuhr läuft, bleibt der Bildschirm an. Das Ziehen von Hindernissen ist flüssiger. Die manuelle Zeit kannst du auch als 1:05,30 eingeben. „Skizze aus Bild“ friert das Handy beim Lesen nicht mehr ein und der Kompass bei „Aufbau vor Ort“ funktioniert auch auf dem iPhone. Das PDF mit Aufbauplan passt auch bei quadratischer Fläche. Ein Parcours aus einem Code wird vor dem Speichern geprüft, beschädigte Daten bringen die App nicht mehr zum Absturz. Das Wiederherstellen eines Backups ersetzt alle Daten, und wenn es scheitert, ändert sich nichts. Ist der Speicher voll, warnt die App, dass eine Änderung nicht gespeichert wurde. Bei schwachem Empfang am Hundeplatz öffnet sich die App innerhalb von 3 Sekunden aus der gespeicherten Version und die Schrift funktioniert auch offline.",
"zapne se po klepnutí na Stojím v rohu":"schaltet sich ein, sobald du auf „Ich stehe in der Ecke“ tippst",
"Je připravená nová verze aplikace.":"Eine neue Version der App ist bereit.",
"Paměť aplikace je plná, poslední změna se neuložila. Odeber podklad z fotky nebo smaž staré parkury v Moje.":"Der Speicher der App ist voll, die letzte Änderung wurde nicht gespeichert. Entferne das Hintergrundfoto oder lösche alte Parcours unter „Meine“.",
"Aplikace se teď jmenuje AgiPlan. Tvoje parkury, psi i běhy zůstaly, jak byly.":"Die App heißt jetzt AgiPlan. Deine Parcours, Hunde und Läufe sind geblieben, wie sie waren.",
