"Bez trasy se kontroluje jen rozmístění překážek. Ostatní pravidla přibydou, až vyznačíš trasu v režimu Trasa.":"Ohne Route wird nur die Anordnung der Hindernisse geprüft. Die übrigen Regeln kommen dazu, sobald du die Route im Modus „Route“ festlegst.",
"Klepnutím na položku se plocha přiblíží k překážkám, kterých se týká. Rozestupy se měří po dráze psa, jak ji ukazuje plán, i se smyčkami otoček. Pravidla platí pro závody, na trénink si můžeš postavit cokoli.":"Tippe auf einen Punkt, um die betroffenen Hindernisse heranzuzoomen. Die Abstände werden entlang der Lauflinie gemessen, wie sie der Plan zeigt, inklusive Wickler-Schleifen. Die Regeln gelten für Turniere, im Training kannst du bauen, was du willst.",
