"Kolbiště podle GPS (Plán → Nástroje): ulož polohu kolbiště, aplikace tě k němu dovede a jeho natočení použije Stavba v terénu i AR":"Ringe per GPS (Plan → Tools): Speichere die Position des Rings, die App führt dich hin, und „Aufbau vor Ort“ sowie AR nutzen seine Ausrichtung",
"Stavba: přiblížení dvěma prsty, natočení skoků kolmo na trasu, kopírování překážky a obrácení trasy":"Aufbau: Zoomen mit zwei Fingern, Sprünge rechtwinklig zur Route ausrichten, Hindernis kopieren und Route umkehren",
"Nové překážky zeď a dvojitý skok, na plánku Start a Cíl, kontrola hlídá překážky přes sebe":"Neue Hindernisse Mauer und Doppelsprung, Start und Ziel auf der Skizze, die Prüfung achtet auf überlappende Hindernisse",
"Deník: postup do vyšší třídy počítá i výsledky z kacr.info, u závodu zapíšeš čas, délku trati a video":"Tagebuch: Der Aufstieg in die nächste Klasse zählt auch Ergebnisse von kacr.info, beim Turnier trägst du Zeit, Parcourslänge und Video ein",
