"AR na place: ve 3D klepni na AR a parkur se položí na skutečný trávník (Chrome na Androidu)":"AR auf dem Platz: Tippe in 3D auf AR, und der Parcours wird auf echten Rasen gestellt (Chrome auf Android)",
