"Parkury, psi a běhy pak budeš mít na všech svých zařízeních. Jde to i bez přihlášení, stačí Pokračovat.":"Parcours, Hunde und Läufe hast du dann auf all deinen Geräten. Es geht auch ohne Anmeldung, tippe einfach auf „Weiter“.",
"Parkury, psi, běhy a deník pak budeš mít na každém zařízení a nezmizí ani se ztraceným telefonem.":"Parcours, Hunde, Läufe und Tagebuch hast du dann auf jedem Gerät, und sie gehen auch mit einem verlorenen Handy nicht verloren.",
