"přihlášení vypršelo, přihlas se znovu":"Anmeldung abgelaufen, melde dich neu an",
"data se mezitím změnila, zkus to znovu":"die Daten haben sich inzwischen geändert, versuch es noch mal",
"v telefonu je plná paměť":"der Speicher des Handys ist voll",
"nepřihlášeno":"nicht angemeldet",
"Přihlas se ke svým datům":"Melde dich an, um deine Daten zu synchronisieren",
"Parkury, psi, běhy a deník pak budeš mít na každém zařízení, kde se přihlásíš, třeba v telefonu i v počítači. Synchronizují se samy a nezmizí ani se ztraceným telefonem.":"Parcours, Hunde, Läufe und Tagebuch hast du dann auf jedem Gerät, auf dem du dich anmeldest, z. B. auf Handy und Computer. Sie synchronisieren sich selbst und gehen auch mit einem verlorenen Handy nicht verloren.",
"Přihlásit přes Google":"Mit Google anmelden",
"Bez přihlášení aplikace funguje dál a data zůstanou jen v tomhle zařízení. Co už v něm máš, se při prvním přihlášení nahraje do účtu.":"Ohne Anmeldung funktioniert die App weiter und die Daten bleiben nur auf diesem Gerät. Was du hier schon hast, wird bei der ersten Anmeldung in dein Konto hochgeladen.",
"Synchronizovat teď":"Jetzt synchronisieren",
"Odhlásit":"Abmelden",
"Odhlásit?":"Abmelden?",
"Odhlášeno":"Abgemeldet",
"Přihlášeno":"Angemeldet",
"Parkury, psi, běhy, deník a nastavení se synchronizují samy při každé změně a při otevření aplikace. Po odhlášení zůstanou data v tomhle zařízení.":"Parcours, Hunde, Läufe, Tagebuch und Einstellungen synchronisieren sich bei jeder Änderung und beim Öffnen der App selbst. Nach dem Abmelden bleiben die Daten auf diesem Gerät.",
"Smazat data z účtu":"Daten im Konto löschen",
"Smazat data z účtu?":"Daten im Konto löschen?",
"Smažou se data uložená na serveru u tvého účtu. V tomhle zařízení zůstanou a odhlásíš se.":"Die Daten deines Kontos auf dem Server werden gelöscht. Auf diesem Gerät bleiben sie, und du wirst abgemeldet.",
"Data z účtu smazána":"Kontodaten gelöscht",
"Data se v tomhle zařízení zůstanou, jen se přestanou synchronizovat.":"Die Daten bleiben auf diesem Gerät, sie werden nur nicht mehr synchronisiert.",
"Data v tomhle zařízení zůstanou, jen se přestanou synchronizovat.":"Die Daten bleiben auf diesem Gerät, sie werden nur nicht mehr synchronisiert.",
"Synchronizuji…":"Synchronisiere…",
"Bez signálu. Změny se pošlou, až bude připojení.":"Kein Empfang. Die Änderungen werden gesendet, sobald du wieder online bist.",
"Data se synchronizují samy.":"Die Daten synchronisieren sich selbst.",
"Přihlášení přes Google se právě zapíná, zkus to prosím později.":"Die Anmeldung mit Google wird gerade eingerichtet, bitte versuch es später.",
"Bez připojení k internetu se přihlásit nedá.":"Ohne Internetverbindung kannst du dich nicht anmelden.",
"Nepovedlo se":"Hat nicht geklappt",
