"V tomhle zařízení jsou data, která patřila jinému účtu. Mám je spojit s tvým účtem, nebo je nahradit daty z účtu?":"Auf diesem Gerät sind Daten, die zu einem anderen Konto gehörten. Soll ich sie mit deinem Konto zusammenführen oder durch die Daten aus deinem Konto ersetzen?",
"Spojit":"Zusammenführen",
"Nahradit daty z účtu":"Durch Kontodaten ersetzen",
