"Do Grade 4 jde postoupit i na body (100 bodů ve třídě). Po výhře zůstáváš ve třídě ještě 25 dní (od 2026 18 dní). Micro do 28 cm se skoky 200 mm platí od 1. 1. 2027. Časové chyby: 1 bod za každou započatou sekundu nad čas; standardní čas vychází z Course Time Matrix (průměr + 10 s).":"Bis Grade 4 kannst du auch über Punkte aufsteigen (100 Punkte in der Klasse). Nach einem Sieg bleibst du noch 25 Tage in der Klasse (ab 2026 18 Tage). Micro bis 28 cm mit 200-mm-Sprüngen gilt ab 1. 1. 2027. Zeitfehler: 1 Punkt für jede angefangene Sekunde über der Zeit; die Standardzeit ergibt sich aus der Course Time Matrix (Durchschnitt + 10 s).",
