"Hoopers: pes běží parkur z oblouků, sudů, plůtků a krátkých tunelů sám a psovod ho vede z prostoru 2 × 2 m (žlutý čtverec). Parkury H1–H3 složil generátor podle pravidel FCI Hoopers: start i cíl obloukem, aspoň polovina oblouků, vzdálenosti mezi překážkami a od psovoda podle třídy. Hodnotí se chyby, maximální čas jsou 3 minuty.":"Hoopers: Der Hund läuft den Parcours aus Hoops, Tonnen, Gates und Tunneln allein, du führst ihn aus einem Führbereich von 2 × 2 m (gelbes Quadrat). Die Parcours H1–H3 hat der Generator nach den FCI-Hoopers-Regeln erstellt: Start und Ziel durch einen Hoop, mindestens die Hälfte Hoops, Abstände zwischen den Hindernissen und zum Führbereich je nach Klasse. Bewertet werden Fehler, die Maximalzeit beträgt 3 Minuten.",
