"Plocha přes celou obrazovku: tlačítko pod plochou schová lišty a souhrn":"Fläche im Vollbild: Der Button unter der Fläche blendet Leisten und Übersicht aus",
"Nový parkur se zeptá na plochu a třídu a otevře se celý; v paletě jsou všechny překážky bez posouvání":"Ein neuer Parcours fragt nach Fläche und Klasse und öffnet sich ganz; in der Palette sind alle Hindernisse ohne Scrollen",
"Kontrola FCI rovnou na ploše i bez trasy: překážky přes sebe, mimo plochu nebo blíž než 1 m se obtáhnou červeně; nové kontroly nájezdu, zdi, dvojitého skoku a tunelů":"FCI-Prüfung direkt auf der Fläche, auch ohne Route: Überlappende Hindernisse, Hindernisse außerhalb der Fläche oder näher als 1 m werden rot umrandet; neue Prüfungen für Anlauf, Mauer, Doppelsprung und Tunnel",
"Znovu vedle Zpět, úprava trasy uprostřed (⋯ u kroku) a uložení parkuru i bez trasy":"Wiederholen neben Zurück, Route in der Mitte bearbeiten (⋯ beim Schritt) und Parcours auch ohne Route speichern",
