"Jedna barva výběru, stejná tlapka všude, větší tlačítka pro prst a tlačítka dlouhých oken vždy vidět":"Eine Auswahlfarbe, überall dieselbe Pfote, größere Buttons für den Finger und die Buttons langer Fenster immer sichtbar",
