"Výsledky se do deníku berou samy. U běhu s trestnými body ťukni, co se stalo, a rozbor Kde ztrácíš body bude přesnější.":"Die Ergebnisse landen automatisch im Tagebuch. Tippe bei einem Lauf mit Fehlerpunkten an, was passiert ist, dann wird die Analyse „Wo du Punkte verlierst“ genauer.",
"Čisté běhy po měsících":"Fehlerfreie Läufe pro Monat",
"Podíl čistých běhů po měsících":"Anteil fehlerfreier Läufe pro Monat",
"Závod":"Turnier",
"Postup se hlídá sám: na Domů vidíš, kolik ti zbývá do vyšší třídy podle pravidel tvé země":"Aufstieg automatisch im Blick: Auf der Startseite siehst du, wie viel dir nach den Regeln deines Landes bis zur nächsten Klasse fehlt",
"Kalkulačka SČP a MČP (Více → Nástroje): časy podle délky trati bez kreslení parkuru":"SZ- und MZ-Rechner (Mehr → Tools): Zeiten aus der Parcourslänge, ohne einen Parcours zu zeichnen",
"Křížení na dráze psovoda: do plánku si označíš přední, zadní a slepé křížení a místa, kde si dát pozor":"Wechsel auf deinem Laufweg: Markiere Front Cross, Rear Cross, Blind Cross und heikle Stellen im Plan",
"Výsledková listina pro pořadatele (Více → Nástroje a v Běhu): pořadí podle FCI, tisk, PDF a kopírování do Excelu":"Ergebnisliste für Veranstalter (Mehr → Tools und unter Lauf): Reihung nach FCI, Druck, PDF und Kopieren nach Excel",
