"Zapsat výsledek":"Ergebnis eintragen",
"Pořadí na startu najdeš u pořadatele, kacr.info ho nezveřejňuje.":"Die Startreihenfolge bekommst du beim Veranstalter, kacr.info veröffentlicht sie nicht.",
