"Odškrtnout vše":"Alle Häkchen entfernen",
"Propoj psa s kacr.info ve Více → Psi.":"Verknüpfe den Hund unter Mehr → Hunde mit kacr.info.",
"Výsledky na kacr.info ještě nejsou. Zkus to později.":"Auf kacr.info sind noch keine Ergebnisse. Versuch es später.",
"Čistě":"Fehlerfrei",
"S chybou":"Mit Fehler",
"S odmítnutím":"Mit Verweigerung",
"Přes standardní čas":"Über der Standardzeit",
"Nejčastěji končíš diskvalifikací.":"Am häufigsten endet es mit Disqualifikation.",
"Bývá to špatná překážka (past u tunelu, druhý konec, odbočka). Před během si projdi pasti v Plánu → Rozbor a trénuj odbočky od tunelů.":"Meist ist es ein falsches Hindernis (Falle am Tunnel, anderes Ende, Abzweigung). Geh vor dem Lauf die Fallen unter Plan → Analyse durch und trainiere das Abdrehen von Tunneln.",
"Nejvíc bodů ztrácíš chybami.":"Die meisten Punkte verlierst du durch Fehler.",
"kacr.info je nerozlišuje: je to shozená tyčka i zóna. Zapiš si u závodu v deníku, co to bylo, a doporučení bude přesnější.":"kacr.info unterscheidet sie nicht: Das sind Stangenabwürfe genauso wie Zonenfehler. Notier dir beim Turnier im Tagebuch, was es war, dann wird die Empfehlung genauer.",
"Nejvíc bodů ztrácíš odmítnutím.":"Die meisten Punkte verlierst du durch Verweigerungen.",
"Odmítnutí bývají u vstupu do slalomu, zadních stran a tunelů, často kvůli pozdnímu povelu. Procvič vstupy a zadní strany.":"Verweigerungen passieren meist am Slalomeingang, bei Backsides und Tunneln, oft wegen eines zu späten Kommandos. Übe Eingänge und Backsides.",
"Nejvíc bodů ztrácíš za čas.":"Die meisten Punkte verlierst du durch die Zeit.",
"Pes je pomalejší než standardní čas. Pomůžou rovnější linie, méně oblouků a dřívější signály.":"Der Hund ist langsamer als die Standardzeit. Geradere Linien, weniger Bögen und frühere Signale helfen.",
"Všechny dokončené běhy bez trestných bodů. Výborně!":"Alle beendeten Läufe ohne Fehlerpunkte. Super!",
"Propoj psa s kacr.info (Více → Psi) a aplikace z výsledků spočítá, kde ztrácíš body a u kterých rozhodčích se ti daří.":"Verknüpfe den Hund mit kacr.info (Mehr → Hunde), dann berechnet die App aus den Ergebnissen, wo du Punkte verlierst und bei welchen Richtern es gut läuft.",
"Načítám podrobnosti běhů z kacr.info…":"Lade Laufdetails von kacr.info…",
"Podrobnosti běhů z kacr.info zatím nejsou stažené.":"Die Laufdetails von kacr.info sind noch nicht geladen.",
"Načti výsledky psa z kacr.info (Více → Psi).":"Lade die Ergebnisse des Hundes von kacr.info (Mehr → Hunde).",
"Podle rozhodčího a povrchu":"Nach Richter und Untergrund",
"Rychlost je medián dokončených běhů. Řádek se ukáže od 2 běhů.":"Das Tempo ist der Median der beendeten Läufe. Eine Zeile erscheint ab 2 Läufen.",
