"Parkury, běhy a deník budeš mít pod ikonou na ploše. Aplikace se otevře přes celou obrazovku a funguje i bez signálu na cvičišti.":"Parcours, Läufe und Tagebuch hast du dann mit einem Tipp auf dem Startbildschirm. Die App öffnet sich im Vollbild und funktioniert auch ohne Empfang am Hundeplatz.",
"Aplikace na ploše má na iPhonu vlastní úložiště. Přihlas se ve Více → Účet, ať se ti parkury přenesou.":"Auf dem iPhone hat die App auf dem Home-Bildschirm einen eigenen Speicher. Melde dich unter Mehr → Konto an, damit deine Parcours übernommen werden.",
"Ťukni na ikonu se šipkou dolů v adresním řádku, nebo na ≡ dole vpravo.":"Tippe auf das Symbol mit dem Pfeil nach unten in der Adressleiste oder auf ≡ unten rechts.",
