"Potvrď Instalovat.":"Bestätige mit „Installieren“.",
"Ikona Pawkur se pak objeví na ploše. Aplikace z ní běží přes celou obrazovku a funguje i bez signálu.":"Das Pawkur-Icon erscheint dann auf dem Startbildschirm. Darüber läuft die App im Vollbild und funktioniert auch ohne Empfang.",
