"Na iPhonu jde aplikace přidat na plochu jen ze Safari. Otevři tuhle stránku v Safari a postupuj takhle:":"Auf dem iPhone kannst du die App nur über Safari zum Home-Bildschirm hinzufügen. Öffne diese Seite in Safari und geh so vor:",
