"Neuložené změny v rozpracovaném parkuru se ztratí. Chceš je zachovat, zruš to a nejdřív plán ulož.":"Nicht gespeicherte Änderungen am angefangenen Parcours gehen verloren. Willst du sie behalten, brich ab und speichere zuerst den Plan.",
