"Na place zmáčkni START, když pes vyběhne, a STOP v cíli. Čas jde zadat i ručně.":"Drück auf dem Platz START, wenn der Hund losläuft, und STOP im Ziel. Die Zeit kannst du auch manuell eingeben.",
