"24\" Choice: pes do 22\" smí skákat 24\", časy má jako 20\". Slalom: Novice 6 tyčí, od Open 12. Bodování ze 100: odmítnutí, špatná překážka a chyba na stole −5 bodů, shozená tyčka a minutá zóna vyřazují (NQ). Časové chyby za každou celou sekundu nad SČP: Novice 1, Open 2, Excellent a Master 3 body; maximální čas je SČP + 20 s. Kvalifikace (Q): aspoň 85 bodů, v Master 100; v Excellent a Master žádná chyba na trati. Titul MACH: 750 bodů (sekunda pod SČP = bod) a 20 dvojitých Q v Master.":"24\" Choice: Ein Hund bis 22\" darf 24\" springen und hat die Zeiten von 20\". Slalom: Novice 6 Stangen, ab Open 12. Wertung von 100 Punkten abwärts: Verweigerung, falsches Hindernis und Fehler am Tisch kosten 5 Punkte, eine gerissene Stange oder eine verpasste Zone bedeutet Ausscheiden (NQ). Zeitfehler für jede volle Sekunde über der SZ: Novice 1, Open 2, Excellent und Master 3 Punkte; die Maximalzeit ist SZ + 20 s. Qualifikation (Q): mindestens 85 Punkte, in Master 100; in Excellent und Master kein Fehler im Parcours. Titel MACH: 750 Punkte (jede Sekunde unter der SZ = 1 Punkt) und 20 Doppel-Q in Master.",
