"Délka trati a vzdálenosti na plánku v metrech, ve stopách, nebo jako u AKC: délka trati v yardech a vzdálenosti ve stopách. Rychlost je u stop a yardů v yardech za sekundu. Parkury se dál ukládají v metrech.":"Parcourslänge und Abstände im Plan in Metern, in Fuß oder wie bei der AKC: Parcourslänge in Yards, Abstände in Fuß. Bei Fuß und Yards ist die Geschwindigkeit in Yards pro Sekunde. Parcours werden weiterhin in Metern gespeichert.",
