"Ulož si, kde stojí kolbiště, a aplikace tě k němu dovede. Zaměřené natočení použije Stavba v terénu a AR na place. Polohy zůstávají v tomhle zařízení a v tvé záloze; s parkurem odejdou, jen když ho sdílíš kódem i s polohou kolbiště.":"Speichere, wo der Ring liegt, dann führt dich die App hin. Die gemessene Ausrichtung nutzen „Aufbau vor Ort“ und „AR auf dem Platz“. Die Positionen bleiben auf diesem Gerät und in deinem Backup; mit einem Parcours gehen sie nur raus, wenn du ihn per Code samt Position des Rings teilst.",
"Hoopers: oblouky, sudy a tunely, bez skoků. Parkury Jumping patří pod Agility.":"Hoopers: Hoops, Tonnen und Tunnel, keine Sprünge. Jumping-Parcours gehören zu Agility.",
"Zavřít vysvětlení":"Erklärung schließen",
"Přidat polohu kolbiště (pro AR a stavbu v terénu)":"Position des Rings mitsenden (für AR und den Aufbau vor Ort)",
"Polohu kolbiště uvidí jen ten, kdo dostane kód. Do galerie ani skupině se neposílá.":"Die Position des Rings sieht nur, wer den Code bekommt. Sie geht nie in die Galerie oder an eine Gruppe.",
"Podle rohů":"Nach Ecken",
"Doladit":"Feinjustieren",
"Doladit polohu":"Position feinjustieren",
"Zem se zatím nenašla. Miř telefonem na zem a pomalu s ním pohybuj.":"Noch kein Boden gefunden. Richte das Handy auf den Boden und beweg es langsam.",
"Zamiř kroužek na stůl nebo na zem a klepni. Model se položí středem.":"Richte den Kreis auf einen Tisch oder den Boden und tippe. Das Modell wird mit der Mitte dort abgestellt.",
"Model stojí. Pusť psa, nebo ho natoč v „Doladit“.":"Das Modell steht. Lass den Hund laufen oder dreh es unter „Feinjustieren“.",
"Parkur stojí natočený podle kolbiště. Kompas může o pár stupňů ujet: dorovnej ho v „Doladit“, nebo polož parkur přesně „Podle rohů“.":"Der Parcours ist nach dem Ring ausgerichtet. Der Kompass kann ein paar Grad abweichen: Korrigier ihn unter „Feinjustieren“ oder platzier den Parcours genau „Nach Ecken“.",
"Dojdi do rohu kolbiště, který je na plánu vlevo nahoře, zamiř na něj zelený kroužek a klepni.":"Geh zur Ecke des Rings, die auf dem Plan oben links ist, richte den grünen Kreis darauf und tippe.",
"Teď dojdi podél dlouhé strany do rohu vpravo nahoře, zamiř na něj zelený kroužek a klepni.":"Geh jetzt an der langen Seite entlang zur Ecke oben rechts, richte den grünen Kreis darauf und tippe.",
"Rohy jsou moc blízko u sebe. Dojdi do rohu vpravo nahoře, na druhý konec dlouhé strany.":"Die Ecken liegen zu nah beieinander. Geh zur Ecke oben rechts, ans andere Ende der langen Seite.",
"AR na place: položení přesně podle dvou rohů kolbiště, doladění o 1° a 25 cm, opravené Položit znovu":"AR auf dem Platz: genau nach zwei Ecken des Rings platzieren, Feinjustieren um 1° und 25 cm, Neu platzieren repariert",
"Kompas v AR, Stavbě v terénu a navigaci ke kolbišti počítá s rozdílem mezi magnetickým a zeměpisným severem":"Der Kompass in AR, beim Aufbau vor Ort und auf dem Weg zum Ring berücksichtigt den Unterschied zwischen magnetischem und geografischem Norden",
