"Podle pravidel USDAA Official Rules & Regulations (kapitoly 1 až 5 a 7) (znění může být novější, ověř na":"Nach den USDAA Official Rules & Regulations (Kapitel 1 bis 5 und 7) (evtl. gibt es eine neuere Fassung, prüf sie auf",
"Performance: skoky o 4\" níž, SČP o 3 s delší (v Masters Standard o 5 s, v Masters Jumpers o 4 s). Dvojitý skok jen v Championship od 16\". Rychlost pro SČP volí rozhodčí v rozsahu z tabulek, nikdy pod minimem; aplikace počítá s minimem, tedy s nejdelším SČP. Maximální čas není. Chyba 5 bodů, časová chyba 1 bod za každou i započatou sekundu nad SČP. Odmítnutí: ve Starters a Advanced Jumpers bez trestu, v Advanced Standard 5 bodů jen na zónové překážce, v Masters 5 bodů a třetí vyřazuje. Špatná trasa: Starters 5, Advanced 20 bodů, Masters vyřazení. Kvalifikace (Q) jen bez trestných bodů. Titul v Masters: 5 Q od 2 rozhodčích, Champion 10 Q.":"Performance: Sprunghöhe 4\" niedriger, SZ 3 s länger (in Masters Standard 5 s, in Masters Jumpers 4 s). Doppelsprung nur in Championship ab 16\". Die Geschwindigkeit für die SZ wird im Bereich aus den Tabellen gewählt, nie unter dem Minimum; die App rechnet mit dem Minimum, also mit der längsten SZ. Eine Maximalzeit gibt es nicht. Ein Fehler kostet 5 Punkte, dazu 1 Zeitfehler für jede angefangene Sekunde über der SZ. Verweigerungen: in Starters und Advanced Jumpers ohne Strafe, in Advanced Standard 5 Punkte nur an einem Zonengerät, in Masters 5 Punkte, und die dritte bedeutet Ausscheiden. Falscher Parcours: Starters 5, Advanced 20 Punkte, Masters Ausscheiden. Qualifikation (Q) nur ohne Fehlerpunkte. Titel in Masters: 5 Q unter 2 Richtern, Champion 10 Q.",
