"Návrh strany psa: u ostrých obratů je psovod uvnitř, mírné zatáčky se dají vést i zvenku. Změny strany: # (FCI chce aspoň 2).":"Vorschlag für die Hundeseite: Bei engen Wendungen ist der Hundeführer innen, sanfte Bögen kann man auch von außen führen. Seitenwechsel: #1 (FCI verlangt mindestens 2).",
