"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Upraveno podle # zapsaného běhu psa. Odhad je nad SČP o # s.":"Hundemodell nach Größe: Tempo in Kurven nach Radius, Beschleunigung, Abbremsen auf den Zonen, im Slalom und auf der Wippe. Angepasst nach #1 erfasstem Lauf des Hundes. Die Schätzung liegt #2 s über der SZ.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Upraveno podle # zapsaného běhu psa.":"Hundemodell nach Größe: Tempo in Kurven nach Radius, Beschleunigung, Abbremsen auf den Zonen, im Slalom und auf der Wippe. Angepasst nach #1 erfasstem Lauf des Hundes.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Upraveno podle # zapsaných běhů psa. Odhad je nad SČP o # s.":"Hundemodell nach Größe: Tempo in Kurven nach Radius, Beschleunigung, Abbremsen auf den Zonen, im Slalom und auf der Wippe. Angepasst nach #1 erfassten Läufen des Hundes. Die Schätzung liegt #2 s über der SZ.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Upraveno podle # zapsaných běhů psa.":"Hundemodell nach Größe: Tempo in Kurven nach Radius, Beschleunigung, Abbremsen auf den Zonen, im Slalom und auf der Wippe. Angepasst nach #1 erfassten Läufen des Hundes.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Až zapíšeš běhy psa, odhad se podle nich upraví. Odhad je nad SČP o # s.":"Hundemodell nach Größe: Tempo in Kurven nach Radius, Beschleunigung, Abbremsen auf den Zonen, im Slalom und auf der Wippe. Sobald du Läufe des Hundes einträgst, passt sich die Schätzung an. Die Schätzung liegt #1 s über der SZ.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Přidej psa ve Více › Psi a odhad bude pro něj. Odhad je nad SČP o # s.":"Hundemodell nach Größe: Tempo in Kurven nach Radius, Beschleunigung, Abbremsen auf den Zonen, im Slalom und auf der Wippe. Füge unter Mehr › Hunde einen Hund hinzu, dann gilt die Schätzung für ihn. Die Schätzung liegt #1 s über der SZ.",
"Přední křížení u #: doběhneš o # s později, než je potřeba. Zkus zadní křížení, nebo psa pošli dopředu a křížení udělej dřív.":"Front Cross bei #1: Du kommst #2 s später an als nötig. Versuch einen Rear Cross oder schick den Hund voraus und wechsle früher.",
"U překážky # jsi o # s za psem. Tady musí pes pracovat na dálku, nebo si zkrať dráhu.":"Bei Hindernis #1 bist du #2 s hinter dem Hund. Hier muss der Hund auf Distanz arbeiten, oder du kürzt deinen Laufweg ab.",
"A další místa: #.":"Und weitere Stellen: #1.",
"Tvoje dráha # m (podle nakreslené Dráhy psovoda), pes uběhne # m. Na startu počítá s odchodem k druhé překážce.":"Dein Laufweg #1 m (nach dem gezeichneten Laufweg), der Hund läuft #2 m. Am Start ist ein Vorsprung bis zum zweiten Hindernis eingerechnet.",
"Tvoje dráha # m (odhad: 2 m od psa na straně návrhu), pes uběhne # m. Na startu počítá s odchodem k druhé překážce.":"Dein Laufweg #1 m (Schätzung: 2 m neben dem Hund auf der vorgeschlagenen Seite), der Hund läuft #2 m. Am Start ist ein Vorsprung bis zum zweiten Hindernis eingerechnet.",
"Klepni, když pes dokončí překážku # (cíl).":"Tippe, wenn der Hund Hindernis #1 beendet (Ziel).",
"Klepni, když pes dokončí překážku #.":"Tippe, wenn der Hund Hindernis #1 beendet.",
"Průměrně # chyb a odmítnutí na běh: vyplatí se kratší sekvence a přesnost před rychlostí.":"Im Schnitt #1 Fehler und Verweigerungen pro Lauf: Kürzere Sequenzen und Genauigkeit vor Tempo zahlen sich aus.",
"Průměrně # chyb a odmítnutí na běh: vyplatí se přesnost před rychlostí.":"Im Schnitt #1 Fehler und Verweigerungen pro Lauf: Genauigkeit vor Tempo zahlt sich aus.",
