"Standardní čas podle AKC: délka trati v yardech děleno rychlostí pro třídu a výšku skoku, v Novice a Open Standard + # s za stůl, v Excellent a Master nejvýš limit pro výšku. Maximální čas je SČP + # s.":"Standardzeit nach AKC: Parcourslänge in Yards geteilt durch die Geschwindigkeit für Klasse und Sprunghöhe, in Novice und Open Standard + # s für den Tisch, in Excellent und Master höchstens das Limit für die Höhe. Die Maximalzeit ist SZ + # s.",
"Parkur stojí podle rohů kolbiště. Rohy jsou od sebe # m, na plánu # m.":"Der Parcours steht nach den Ecken des Rings. Die Ecken liegen # m auseinander, auf dem Plan # m.",
"Rohy jsou od sebe # m, ale plán má # m. Zkontroluj rohy a zkus to znovu „Podle rohů“, nebo dorovnej v „Doladit“.":"Die Ecken liegen # m auseinander, der Plan hat aber # m. Prüf die Ecken und versuch es noch mal „Nach Ecken“ oder korrigier unter „Feinjustieren“.",
